Here's an implementation of a Binary Search Tree (BST) in Python:

```python
class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        """Insert a value into the BST."""
        if not self.root:
            self.root = Node(value)
        else:
            self._insert(self.root, value)

    def _insert(self, node, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(value)
            else:
                self._insert(node.left, value)
        elif value > node.value:
            if node.right is None:
                node.right = Node(value)
            else:
                self._insert(node.right, value)

    def search(self, value):
        """Search for a value in the BST. Returns True if found."""
        return self._search(self.root, value)

    def _search(self, node, value):
        if node is None:
            return False
        if value == node.value:
            return True
        elif value < node.value:
            return self._search(node.left, value)
        else:
            return self._search(node.right, value)

    def inorder(self):
        """Return inorder traversal as a list."""
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, result):
        if node:
            self._inorder(node.left, result)
            result.append(node.value)
            self._inorder(node.right, result)

# Example usage:
bst = BinarySearchTree()
for v in [5, 3, 7, 2, 4, 8]:
    bst.insert(v)
print(bst.inorder())  # [2, 3, 4, 5, 7, 8]
print(bst.search(4))  # True
print(bst.search(9))  # False
```

The BST maintains the property: left child < parent < right child. Insertion and search both run in O(log n) average time for balanced trees. The inorder traversal returns values in sorted order.
